param([Parameter(Mandatory=$true)][string]$VariantsCsv,[int]$Runs=3)
$ErrorActionPreference='Stop';$Variants=$VariantsCsv -split ','
$root='C:\Users\home\AppData\Local\Temp\hpc-client-gui-r14-debug-20261118\repo';$work=Join-Path $env:LOCALAPPDATA 'Temp\hpc-client-gui-r14-native-crash-20261118';$sessionId=(Get-Process -Id $PID).SessionId;$py=Join-Path $env:LOCALAPPDATA 'Programs\Python\Python314\python.exe'
foreach($variant in $Variants){for($i=1;$i -le $Runs;$i++){$out=Join-Path $work "$variant-$i.stdout";$err=Join-Path $work "$variant-$i.stderr";$start=[DateTime]::UtcNow;$p=Start-Process -FilePath $py -ArgumentList @('-X','faulthandler',(Join-Path $work 'variant_pair_runner.py'),$variant) -WorkingDirectory $root -PassThru -Wait -WindowStyle Hidden -RedirectStandardOutput $out -RedirectStandardError $err;$r=[ordered]@{variant=$variant;run=$i;pid=$p.Id;session=$sessionId;exit=$p.ExitCode;startUtc=$start.ToString('o');endUtc=[DateTime]::UtcNow.ToString('o');stdout=$out;stderr=$err};$r|ConvertTo-Json -Compress|Set-Content -LiteralPath (Join-Path $work "$variant-$i.result.json") -Encoding utf8}}
